// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the two 32-byte words that form the first two immutable-arg slots (addresses are 20 bytes, but placed in 32-byte words)
    function testFuzz_property(bytes32 slot0, bytes32 slot1) public {
        // General idea: the reference implementation's owner() reads the address from immutable args offset 0x0
        // The mutant reads from 0x20 instead. We construct a calldata blob that would be used as immutable args
        // and test that owner() returns the address stored in slot0 (lower 20 bytes of slot0). If slot0 != slot1
        // then the mutant would return a different address for some fuzz inputs. We ensure we pick a case
        // where slot0 and slot1 differ so the property distinguishes implementations.

        // Avoid the trivial case where both slots are equal (then mutant and ref may return same owner).
        // Keep domain wide: allow all inputs but skip equal-slot cases since they don't discriminate.
        if (slot0 == slot1) return;

        // We want to test the owner() pure view function on the deployed clone contract 'c'.
        // The C contract's owner() reads immutable args from calldata of the clone at offsets.
        // To exercise C.owner() on the deployed implementation (not a clone), we can directly call owner()
        // because owner() is a pure function that uses _getArgAddress which reads from calldatasize() relative
        // offsets; when called on the implementation contract (not a clone), immutable args aren't present.
        // However the property we assert is purely about the mapping: owner() returns the address at slot0.
        // To create a calldataload environment where owner() will read our supplied immutable args, we use
        // a low-level staticcall to the contract address with crafted calldata that mimics how clones append
        // immutable args to calldata: the owner() function selector (4 bytes) plus the immutable args appended
        // at the end. We build calldata: selector(owner()) || padding (none) || slot0 || slot1 || trailing length bytes
        // But owner() expects to find immutable args at the end of calldata based on _getImmutableArgsOffset which
        // reads its offset from the last two bytes. To emulate a realistic clone immutables layout, we must append
        // a two-byte length descriptor equal to (number of extra bytes) and include the two slots as the extra bytes.

        // Build owner() selector
        bytes4 sel = bytes4(keccak256("owner()"));

        // Construct 'extra' immutable args as slot0 then slot1 (each 32 bytes), followed by a 2-byte length trailer
        bytes memory imm = new bytes(32 * 2 + 2);
        assembly {
            // store slot0 at imm + 32 (skip length prefix of bytes)
            mstore(add(imm, 32), slot0)
            // store slot1 at imm + 64
            mstore(add(imm, 64), slot1)
        }
        // set the last two bytes to the extra length (2 * 32 = 64 bytes -> plus the 2 trailer bytes => 66 -> but the code in clone expects extraLength=data.length+2 and later stores shl(240, extraLength) (one byte) ???
        // Simpler: we emulate the expected layout by making the two trailer bytes equal to 66 (0x0042) placed at the final two bytes
        uint16 extraLen = uint16(64 + 2); // 66 bytes
        imm[imm.length - 2] = bytes1(uint8(extraLen >> 8));
        imm[imm.length - 1] = bytes1(uint8(extraLen & 0xff));

        // Compose final calldata: selector || imm
        bytes memory callData = abi.encodePacked(sel, imm);

        // Do a staticcall to c with the crafted calldata
        (bool ok, bytes memory ret) = address(c).staticcall(callData);

        // We expect the call to succeed (owner() is pure and should not revert). If it reverts, treat test as failing to exercise; but per rules, we must assert a fact on c.
        // Determine the returned address from the reference implementation: it should be the low 20 bytes of slot0.
        address expected;
        assembly {
            expected := shr(0x60, mload(add(callData, 36))) // slot0 is at callData offset 4 -> mload(add(callData,36))
        }

        // Interpret returned data: owner() returns abi-encoded address (32 bytes)
        address got = address(0);
        if (ok && ret.length >= 32) {
            assembly { got := mload(add(ret,32)) }
        }

        // The universal property: for any imm args where slot0 != slot1, the reference returns the address in slot0.
        assertTrue(ok && got == expected);
    }
}

