pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz two 32-byte words that will simulate the first two immutable arg slots
    function testFuzz_property(bytes32 slot0, bytes32 slot1) public {
        // We will encode two 32-byte words as if they were the first two immutable args
        // The rule: reference.owner() always returns the address encoded in slot0 (first slot)
        // The mutant returns the address encoded in slot1. When the two addresses differ,
        // the mutant will produce a different owner. We assert that owner() equals the
        // low 20 bytes of slot0 (as address). This holds for the reference for all inputs.

        // Make admissible domain wide but avoid the trivial case where both slots encode the same address
        // (we still allow equal slots; the assertion will hold there too). No tight assumptions needed.

        // Interpret slot0 as an address: low 20 bytes of slot0.
        address expectedOwner = address(uint160(uint256(slot0)));

        // Call the deployed reference contract's owner() and compare
        address got;
        try c.owner() returns (address a) {
            got = a;
        } catch {
            // owner() is a pure view and should not revert; if it does, mark test failure by forcing a mismatch
            assertTrue(false);
            return;
        }

        // Single universal assertion: reference contract returns the address encoded in the first immutable slot
        assertTrue(got == expectedOwner);
    }
}

