pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the two 32-byte words that would occupy the first two immutable arg slots
    function testFuzz_property(bytes32 slot0, bytes32 slot1) public {
        // Keep the domain wide but avoid the degenerate case where both encoded addresses are equal
        // so that the mutant and reference can be distinguished when they differ.
        // Interpret the first 20 bytes of each slot as an address (left aligned in the 32-byte word like abi.encodePacked(address)).
        address expected = address(uint160(uint256(slot0)));
        address other = address(uint160(uint256(slot1)));

        // allow all combinations; but if they are equal the mutant won't be distinguishable — skip that case
        vm.assume(expected != other);

        // The property to check: owner() returns the address encoded in slot0.
        // This must hold for the reference C for ALL inputs. The mutant (which reads slot at offset 0x20)
        // will return `other` for some inputs, causing the assertion to fail.

        address got = c.owner();

        assertTrue(got == expected);
    }
}

