pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz: bytes calldata that will become the contract's calldata when calling collateral via a low-level call
    // We use a low-level call to supply arbitrary calldata so that the two offsets 0x14 and 0x18 may differ.
    function testFuzz_property(bytes memory fuzzCalldata) public {
        // Make sure calldata is large enough so both offsets 0x14 and 0x18 are readable when reading 32 bytes
        // We allow smaller inputs but then both reads will be zero and equal; to find difference we need length >= 0x3a
        // Keep domain wide but require at least 0x3a bytes so offset+32 is in bounds of typical calldata accesses.
        // 0x14 + 32 = 0x34, but to be safe for 0x18+32 = 0x3a, require >= 0x3a
        if (fuzzCalldata.length < 0x3a) {
            // pad to required length deterministically so fuzzer can still explore shorter inputs
            bytes memory padded = new bytes(0x3a);
            for (uint256 i = 0; i < fuzzCalldata.length; i++) {
                padded[i] = fuzzCalldata[i];
            }
            fuzzCalldata = padded;
        }

        // We will perform a low-level staticcall to the contract's collateral() selector with arbitrary calldata suffix
        // Build calldata: function selector of collateral() is the 4 byte selector of "collateral()"
        bytes memory callData = new bytes(4 + fuzzCalldata.length);
        bytes4 sel = bytes4(keccak256("collateral()"));
        assembly {
            mstore(add(callData, 32), shl(224, sel))
        }
        // copy fuzzCalldata into callData after 4 bytes
        for (uint256 i = 0; i < fuzzCalldata.length; i++) {
            callData[4 + i] = fuzzCalldata[i];
        }

        // Call the reference contract's collateral via low-level staticcall to control calldata bytes
        (bool ok, bytes memory ret) = address(c).staticcall(callData);
        // If call reverted, treat as not-ok but both reference and mutant would revert similarly for pure view; still assert on ok path only.
        // We assert that when the call succeeds, the returned address equals the 20 bytes located at calldata offset 0x14 in the supplied calldata.
        // Compute expected address by reading 32 bytes from callData at offset 0x14 and shifting down.
        address expected;
        {
            // offset within callData: calldata presented to contract excludes the 4-byte selector when the contract reads calldataload at add(offset, argOffset)
            // The contract's _getArgAddress uses _getImmutableArgsOffset which depends on calldatasize and encoded immutables at end; however for the purpose of distinguishing 0x14 vs 0x18,
            // we probe the bytes we appended and construct the two 32-byte words at positions 0x14 and 0x18 relative to the contract's calldata start.
            // Because we supply extra bytes after the selector, the contract will read relative to its calldatasize; here we simply extract the 32 bytes at position (4 + 0x14) in our callData buffer, which corresponds to calldata offset 0x14 inside the contract's view of calldata (selector excluded by calldataload behavior is not excluded; calldataload sees the full calldata including selector, so positions align).
            uint256 word;
            // read 32 bytes starting at index (4 + 0x14)
            uint256 pos = 4 + 0x14;
            assembly {
                word := mload(add(add(callData, 32), pos))
            }
            expected = address(uint160(uint256(word) >> 96)); // shift down to 20 bytes
        }

        // Only assert when call succeeded and returned 32 bytes (ABI-encoded address)
        if (ok && ret.length >= 32) {
            address got;
            assembly {
                got := mload(add(ret, 32))
            }
            // The universal property: for any calldata, the correct C returns the address located at calldata offset 0x14; the mutant reading 0x18 will differ for some inputs where bytes at 0x14 != bytes at 0x18.
            assertTrue(got == expected);
        } else {
            // If call reverted or returned unexpectedly small, still assert true on ok==false is not allowed; require that call succeeded and returned 32 bytes
            // But to keep property universal for all inputs, we accept reverts by asserting ok == false implies nothing; instead we assert ok == true && ret.length >= 32
            // However rules require exactly one assertTrue reading c; we already have one in the ok path. For paths where ok==false we must still make a single assertTrue.
            // So in revert case we assert that ok == false is true (i.e., call reverted). This will hold for both reference and mutant in those cases.
            assertTrue(ok == false || (ok == true && ret.length >= 32));
        }
    }
}

