import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // We fuzz a bytes input that will be interpreted as calldata for the immutable args when deployed via clone creation.
    // The reference contract's collateral() reads address at offset 0x14; the mutant reads 0x10. We construct calldata
    // shaped like the clone's appended immutable args and call collateral() via low-level call with that calldata.
    // The general property: for any calldata, the correct contract's collateral() returns the address encoded at 0x14.
    // We therefore assert that calling the contract's public collateral() (via encoding calldata that places an address
    // at offset 0x14) returns that address. The mutant that reads 0x10 will sometimes return a different address.
    function testFuzz_property(bytes memory immArgs, address a0, address a1, address a2) public {
        // Keep immArgs length reasonable to avoid extreme memory use, but allow wide space.
        if (immArgs.length > 128) return;

        // We'll craft calldata that mimics call data where the clone's immutable args are appended at the end.
        // The Clone._getArgAddress reads from (offset + argOffset) of calldata where offset is computed from calldatasize.
        // To simplify, we will call collateral() directly: its selector is used and calldata is whatever we append.
        // We need to place three addresses in the trailing calldata such that the address at position 0x14 is a1.
        // Build calldata: function selector (4 bytes) + padding to ensure positions align so that calldatasize - offset picks
        // the right position. For our test we directly craft calldata where at absolute position (4 + 0x14) we place a1.

        bytes memory sel = abi.encodeWithSelector(bytes4(keccak256("collateral()")));

        // Prepare payload ensuring length > 4+0x14
        uint256 minLen = 4 + 0x20; // ensure space
        uint256 targetPos = 4 + 0x14; // where reference reads the address (higher 12 bytes zeroed in calldataload)
        uint256 finalLen = targetPos + 32;
        if (finalLen < minLen) finalLen = minLen;

        bytes memory callData = new bytes(finalLen);

        // copy selector
        for (uint256 i = 0; i < 4; i++) {
            callData[i] = sel[i];
        }

        // fill rest with immArgs if provided (but do not exceed bounds)
        for (uint256 i = 0; i < immArgs.length && 4 + i < callData.length; i++) {
            callData[4 + i] = immArgs[i];
        }

        // Place addresses a0, a1, a2 at chosen absolute positions to create a distinguishing layout.
        // We put a0 at offset 4 + 0x10 (where mutant reads), a1 at 4 + 0x14 (where reference reads), a2 somewhere else.
        assembly {
            // write a0 at 4 + 0x10
            mstore(add(add(callData, 32), add(4, 0x10)), shl(96, a0))
            // write a1 at 4 + 0x14
            mstore(add(add(callData, 32), add(4, 0x14)), shl(96, a1))
            // write a2 at 4 + 0x24 (just extra)
            mstore(add(add(callData, 32), add(4, 0x24)), shl(96, a2))
        }

        // Now perform a low-level call to collateral() with our crafted calldata and decode returned address.
        (bool ok, bytes memory ret) = address(c).call(callData);

        // Only consider completed calls (should not revert). If it reverts, we cannot observe collateral() and skip.
        if (!ok) return;

        // Decode returned address
        address returned;
        if (ret.length >= 32) {
            assembly { returned := mload(add(ret, 32)) }
        } else if (ret.length == 20) {
            // unlikely, but handle compact return
            bytes20 b;
            assembly { b := mload(add(ret, 32)) }
            returned = address(uint160(uint256(uint160(b))));
        } else {
            return; // unexpected shape
        }

        // The reference contract reads the address at offset 0x14, which we set to a1. Therefore returned == a1 for all inputs.
        // This is the single assertion: the correct contract always returns the address we placed at 0x14.
        assertTrue(returned == a1);
    }
}

